sections.body:
保存为 judge-audit.mjs，运行 node judge-audit.mjs，无额外依赖。输入每行依次是正序、反序的票；本例只检查票的映射与计数，不解析原始模型回复，也不验证理由。生产数据应额外核对 sceneId、候选内容哈希和请求编号，防止把不同简报的两张票配成一对。

```javascript
/**
 * @file Reconcile two display orders in an original game-design review.
 * @author liliwei
 * @date 2026-11-22
 * @LastEditors liliwei
 * @LastEditTime 2026-11-22
 */
/**
 * @param {string|null} forward Vote with A=X and B=Y; null means unusable.
 * @param {string|null} reverse Vote with A=Y and B=X; null means unusable.
 * @returns {string} X, Y, tie, conflict, or incomplete.
 */
export function reconcile(forward, reverse) {
  const allowed = new Set(['A', 'B', 'tie', null]);
  if (!allowed.has(forward) || !allowed.has(reverse)) {
    throw new TypeError('Invalid vote');
  }
  if (forward === null || reverse === null) return 'incomplete';
  const first = { A: 'X', B: 'Y', tie: 'tie' }[forward];
  const second = { A: 'Y', B: 'X', tie: 'tie' }[reverse];
  return first === second ? first : 'conflict';
}
/**
 * @param {Array<Array<string|null>>} pairs One forward/reverse pair per scene.
 * @returns {object} Counts and rates; empty denominators produce null.
 */
export function summarize(pairs) {
  if (!Array.isArray(pairs)) throw new TypeError('Expected pairs');
  const counts = { X: 0, Y: 0, tie: 0, conflict: 0, incomplete: 0 };
  const outcomes = [];
  for (const pair of pairs) {
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError('Expected exactly two votes');
    }
    const result = reconcile(pair[0], pair[1]);
    outcomes.push(result);
    counts[result]++;
  }
  const total = pairs.length;
  const complete = total - counts.incomplete;
  return {
    outcomes, counts, total, complete,
    consistency: complete ? (counts.X + counts.Y + counts.tie) / complete : null,
    decisiveCoverage: total ? (counts.X + counts.Y) / total : null
  };
}
const pairs = [
  ['A', 'B'], ['B', 'A'], ['A', 'A'],
  ['B', 'B'], ['tie', 'tie'], ['A', null]
];
console.log(JSON.stringify(summarize(pairs), null, 2));
```

反序的 B 对应 X，所以 A/B 是对 X 的稳定偏好；反序的 A 对应 Y，所以 A/A 是冲突。两次 tie 才归为稳定平局；一票 tie、一票选边也算冲突。一端无有效票就归 incomplete，不能丢掉整行后假装这张简报从未评过。
